414	/*
415	** Free memory that might be associated with a particular database
416	** connection.  Calling sqlite3DbFree(D,X) for X==0 is a harmless no-op.
417	** The sqlite3DbFreeNN(D,X) version requires that X be non-NULL.
418	*/
419	void sqlite3DbFreeNN(sqlite3 *db, void *p){
420	  assert( db==0 || sqlite3_mutex_held(db->mutex) );
421	  assert( p!=0 );
422	  if( db ){
423	    if( ((uptr)p)<(uptr)(db->lookaside.pEnd) ){
424	#ifndef SQLITE_OMIT_TWOSIZE_LOOKASIDE
425	      if( ((uptr)p)>=(uptr)(db->lookaside.pMiddle) ){
426	        LookasideSlot *pBuf = (LookasideSlot*)p;
427	        assert( db->pnBytesFreed==0 );
428	#ifdef SQLITE_DEBUG
429	        memset(p, 0xaa, LOOKASIDE_SMALL);  /* Trash freed content */
430	#endif
431	        pBuf->pNext = db->lookaside.pSmallFree;
432	        db->lookaside.pSmallFree = pBuf;
433	        return;
434	      }
435	#endif /* SQLITE_OMIT_TWOSIZE_LOOKASIDE */
436	      if( ((uptr)p)>=(uptr)(db->lookaside.pStart) ){
437	        LookasideSlot *pBuf = (LookasideSlot*)p;
438	        assert( db->pnBytesFreed==0 );
439	#ifdef SQLITE_DEBUG
440	        memset(p, 0xaa, db->lookaside.szTrue);  /* Trash freed content */
441	#endif
442	        pBuf->pNext = db->lookaside.pFree;
443	        db->lookaside.pFree = pBuf;
444	        return;
445	      }
446	    }
447	    if( db->pnBytesFreed ){
448	      measureAllocationSize(db, p);
449	      return;
450	    }
451	  }
452	  assert( sqlite3MemdebugHasType(p, (MEMTYPE_LOOKASIDE|MEMTYPE_HEAP)) );
453	  assert( sqlite3MemdebugNoType(p, (u8)~(MEMTYPE_LOOKASIDE|MEMTYPE_HEAP)) );
454	  assert( db!=0 || sqlite3MemdebugNoType(p, MEMTYPE_LOOKASIDE) );
455	  sqlite3MemdebugSetType(p, MEMTYPE_HEAP);
456	  sqlite3_free(p);
457	}
458	void sqlite3DbNNFreeNN(sqlite3 *db, void *p){
459	  assert( db!=0 );
460	  assert( sqlite3_mutex_held(db->mutex) );
461	  assert( p!=0 );
462	  if( ((uptr)p)<(uptr)(db->lookaside.pEnd) ){
463	#ifndef SQLITE_OMIT_TWOSIZE_LOOKASIDE
464	    if( ((uptr)p)>=(uptr)(db->lookaside.pMiddle) ){
465	      LookasideSlot *pBuf = (LookasideSlot*)p;
466	      assert( db->pnBytesFreed==0 );
467	#ifdef SQLITE_DEBUG
468	      memset(p, 0xaa, LOOKASIDE_SMALL);  /* Trash freed content */
469	#endif
470	      pBuf->pNext = db->lookaside.pSmallFree;
471	      db->lookaside.pSmallFree = pBuf;
472	      return;
473	    }
474	#endif /* SQLITE_OMIT_TWOSIZE_LOOKASIDE */
475	    if( ((uptr)p)>=(uptr)(db->lookaside.pStart) ){
476	      LookasideSlot *pBuf = (LookasideSlot*)p;
477	      assert( db->pnBytesFreed==0 );
478	#ifdef SQLITE_DEBUG
479	      memset(p, 0xaa, db->lookaside.szTrue);  /* Trash freed content */
480	#endif
481	      pBuf->pNext = db->lookaside.pFree;
482	      db->lookaside.pFree = pBuf;
483	      return;
484	    }
485	  }
486	  if( db->pnBytesFreed ){
487	    measureAllocationSize(db, p);
488	    return;
489	  }
490	  assert( sqlite3MemdebugHasType(p, (MEMTYPE_LOOKASIDE|MEMTYPE_HEAP)) );
491	  assert( sqlite3MemdebugNoType(p, (u8)~(MEMTYPE_LOOKASIDE|MEMTYPE_HEAP)) );
492	  sqlite3MemdebugSetType(p, MEMTYPE_HEAP);
493	  sqlite3_free(p);
494	}
