//! L0 基础设施层 — 字符串/内存/哈希/随机/UTF8 工具。
//!
//! 对应 C 源文件 `util.c` / `malloc.c` / `printf.c` / `random.c` / `utf.c` 等。
//! 本子任务(T-0002)只实现 `alloc` 子模块;其余后续任务再补。

pub mod alloc;

//! 内存分配子系统。
//!
//! 严格对齐 C 端 [`sqlite-source/src/malloc.c`] 的内部 API:
//!
//! - `malloc(n <= 0)` → `NULL`
//! - `malloc64(n == 0 || n > SQLITE_MAX_ALLOCATION_SIZE)` → `NULL`
//! - `realloc(NULL, n)` 行为同 `malloc64(n)`
//! - `realloc(p, 0)` 释放 `p` 并返回 `NULL`
//! - `realloc(p, n)` 失败时原指针保留(写 `db.malloc_failed`)
//! - `free(NULL)` 是 no-op
//! - OOM 不会 `panic`;会写 `db.malloc_failed`
//!
//! 内部用 [`std::alloc::Global`] + 显式 [`Layout`],8 字节对齐 — 与 C 端
//! `EIGHT_BYTE_ALIGNMENT(p)` 断言一致(见 `sqlite3Malloc` 末尾 `assert`)。

use std::alloc::{GlobalAlloc, Layout};
use std::ffi::c_void;
use std::ptr;

use crate::handle::SqliteDb;

/// C 端 `SQLITE_MAX_ALLOCATION_SIZE`(`sqliteLimit.h` 定义为 `0x7FFFFDFF = 2_147_483_391`)。
/// 超过此大小的分配请求一律返回 `NULL`,且**不**写 `db.malloc_failed`(对齐
/// C 端 `sqlite3Malloc` 第一行的边界检查)。
pub const SQLITE_MAX_ALLOCATION_SIZE: u64 = 2_147_483_391;

/// 用户分配 8 字节对齐 — 对齐 C 端 `EIGHT_BYTE_ALIGNMENT` 宏。
const ALLOC_ALIGN: usize = 8;

/// 分配头:放在用户指针之前的 8 字节,记录用户请求的真实 size。
///
/// 之所以需要头: [`std::alloc::GlobalAlloc::dealloc`] 要求传入与 `alloc`
/// 完全相同的 [`Layout`](含 `size`)。C 端 `mem1.c` / `mem5.c` 在分配时
/// 也写入 size 头(见 `malloc.c` 中 `sqlite3MallocSize(p)` 调用
/// `xSize(p)`)。我们采用同样策略。
#[repr(C)]
struct Header {
    /// 用户请求的字节数(≤ [`SQLITE_MAX_ALLOCATION_SIZE`])。
    size: u64,
}

const HEADER_SIZE: usize = core::mem::size_of::<Header>(); // 8

/// 内部 API 命名空间 — 对应 C 端 `sqlite3Malloc*` / `sqlite3_free` /
/// `sqlite3Realloc` / `sqlite3DbMalloc*` 家族。
///
/// 公共 FFI 入口(`sqlite3_malloc` / `sqlite3_malloc64` / `sqlite3_free`)
/// 位于 [`crate::api`],是本类型的 thin wrapper。
pub struct Malloc;

impl Malloc {
    /// `sqlite3_malloc(n)`:参数 `n: c_int`,`n <= 0` 返回 `NULL`。
    ///
    /// `db` 可选:为 `Some(&db)` 时,真正 OOM 会写 `db.malloc_failed`。
    /// `n <= 0` / `n > SQLITE_MAX_ALLOCATION_SIZE` 的"边界拒绝"**不**写
    /// 标志(对齐 C 行为 — 见 `sqlite3Malloc` 第 297-309 行)。
    #[inline]
    pub fn malloc(n: i32, db: Option<&SqliteDb>) -> *mut c_void {
        if n <= 0 {
            return ptr::null_mut();
        }
        Self::malloc64(n as u64, db)
    }

    /// `sqlite3_malloc64(n)` / `sqlite3Malloc(n)`:
    /// `n == 0` 或 `n > SQLITE_MAX_ALLOCATION_SIZE` 返回 `NULL`。
    pub fn malloc64(n: u64, db: Option<&SqliteDb>) -> *mut c_void {
        if n == 0 || n > SQLITE_MAX_ALLOCATION_SIZE {
            return ptr::null_mut();
        }
        // 用户 size + 头部 size,不会溢出(n ≤ MAX < 2^31, header = 8)
        let total = (n as usize).wrapping_add(HEADER_SIZE);
        let layout = match Layout::from_size_align(total, ALLOC_ALIGN) {
            Ok(l) => l,
            Err(_) => {
                if let Some(db) = db {
                    db.set_malloc_failed();
                }
                return ptr::null_mut();
            }
        };
        // SAFETY: `layout` 合法(对齐 = 8, size > 0),`GlobalAlloc::alloc`
        // 在 OOM 时返回 `null` 而非 `panic`(由 `Global` impl 保证)。
        let raw = unsafe { std::alloc::Global.alloc(layout) };
        if raw.is_null() {
            if let Some(db) = db {
                db.set_malloc_failed();
            }
            return ptr::null_mut();
        }
        // 写 size 头
        // SAFETY: `raw` 由 `alloc` 返回,长度 ≥ `layout.size`,前 8 字节可写。
        unsafe {
            (raw as *mut Header).write(Header { size: n });
        }
        // 返回用户区(头部之后)
        // SAFETY: HEADER_SIZE = 8,`alloc` 保证对齐 ≥ 8,所以 `raw + 8` 仍
        // 8 字节对齐。
        unsafe { raw.add(HEADER_SIZE) as *mut c_void }
    }

    /// `sqlite3_realloc(pOld, n)` / `sqlite3Realloc(pOld, nBytes)`。
    ///
    /// 行为:
    /// - `pOld == NULL` → 等价于 `malloc64(nBytes)`(`nBytes` ≤ MAX 校验同
    ///   `malloc64`)
    /// - `nBytes == 0`(或 `< 0`)→ 释放 `pOld` 并返回 `NULL`
    /// - `nBytes > SQLITE_MAX_ALLOCATION_SIZE` → 返回 `NULL`,**不**写
    ///   `malloc_failed`,原指针仍可用
    /// - OOM → 返回 `NULL`,**原指针仍有效**(关键契约 — 对应 C 端
    ///   `sqlite3DbReallocFinish` 的 `if( !pNew ) sqlite3OomFault(db)` 路径)
    pub fn realloc(p_old: *mut c_void, n: i64, db: Option<&SqliteDb>) -> *mut c_void {
        if p_old.is_null() {
            return Self::malloc64(n as u64, db);
        }
        if n <= 0 {
            // C 端 `sqlite3_realloc` 注释 IMP: R-26507-47431:`n<0` 当 `n=0` 处理
            Self::free(p_old);
            return ptr::null_mut();
        }
        let n = n as u64; // safe:已确认 n > 0
        if n > SQLITE_MAX_ALLOCATION_SIZE {
            return ptr::null_mut();
        }
        // 取旧 size
        // SAFETY: `p_old` 由本模块分配,头部 8 字节可读。
        let old_size = unsafe { (p_old as *const Header).sub(1).read().size };
        // 分配新块
        let new_ptr = Self::malloc64(n, db);
        if new_ptr.is_null() {
            // 真正 OOM 时 `malloc64` 已写 `malloc_failed`;旧指针保留不动。
            return ptr::null_mut();
        }
        // 复制旧数据(取 `min(old, new)` 字节 — 严格不越界任一方)
        let copy_len = (old_size as usize).min(n as usize);
        if copy_len > 0 {
            // SAFETY:
            // - `p_old` 至少 `old_size` 字节可读(由本模块 alloc 时写入头部)
            // - `new_ptr` 至少 `n` 字节可写(由 `malloc64` 保证)
            // - `copy_len = min(old, new)`,不越界任一方
            // - 区域不重叠(新块是新分配)
            unsafe {
                ptr::copy_nonoverlapping(p_old as *const u8, new_ptr as *mut u8, copy_len);
            }
        }
        // 释放旧块
        Self::free(p_old);
        new_ptr
    }

    /// `sqlite3_free(p)`:`p == NULL` 时是 no-op(对齐 C 端
    /// `sqlite3_free` 注释 IMP: R-49053-54554)。
    pub fn free(p: *mut c_void) {
        if p.is_null() {
            return;
        }
        // 读取 size 头
        // SAFETY: `p` 由本模块 `malloc` / `realloc` 分配,头部 8 字节在
        // 用户区前 8 字节,可读。
        let header_ptr = unsafe { (p as *const Header).sub(1) };
        // SAFETY: `header_ptr` 是有效对齐(8)、可读的 `*const Header`。
        let size = unsafe { header_ptr.read().size } as usize;
        let total = size.wrapping_add(HEADER_SIZE);
        let layout = match Layout::from_size_align(total, ALLOC_ALIGN) {
            Ok(l) => l,
            Err(_) => return, // 不应发生 — `malloc` 时已校验过
        };
        // SAFETY:
        // - 用户区前的 raw 指针 = `p - HEADER_SIZE`,由 `alloc` 返回
        // - `layout` 与 `malloc` 时完全一致(size + HEADER, align = 8)
        unsafe {
            std::alloc::Global.dealloc(header_ptr as *mut u8, layout);
        }
    }
}

//! FFI 公开 API 层。
//!
//! 对应 sqlite3.h 中的 C 函数。每个函数必须是 `#[no_mangle] pub unsafe extern "C"`,
//! 签名与官方保持 byte-for-byte 一致(指针宽度、整数宽度、调用约定)。
//!
//! 当前 P0 阶段只实现 4 个最小可验证函数:
//!  - `sqlite3_libversion`
//!  - `sqlite3_libversion_number`
//!  - `sqlite3_open`            (桩 — 分配 handle,返回 OK)
//!  - `sqlite3_close`           (桩 — 释放 handle,返回 OK)
//! 后续子任务会把它们替换为真实实现。

use std::ffi::{c_char, c_int, c_void, CStr};

use crate::error::SqliteError;
use crate::handle::SqliteDb;
use crate::util::alloc::Malloc;

/// 返回 SQLite 版本字符串。生命周期 = 进程,不需要 free。
///
/// C 契约:`const char *sqlite3_libversion(void);`
#[no_mangle]
pub unsafe extern "C" fn sqlite3_libversion() -> *const c_char {
    // 'static 字符串嵌入二进制
    SQLITE_VERSION_STR.as_ptr() as *const c_char
}

/// 返回 SQLite 版本号(形如 3054000 = 3.54.0)。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_libversion_number() -> c_int {
    crate::SQLITE_VERSION_NUMBER
}

/// 打开/创建数据库。P0 桩:接受任意 filename,分配一个 handle 写回。
///
/// C 契约:`int sqlite3_open(const char *filename, sqlite3 **ppDb);`
///
/// # Safety
/// - `filename` 必须是 NUL 结尾的 UTF-8 字符串(可为 null)
/// - `pp_db` 必须是非空指针
#[no_mangle]
pub unsafe extern "C" fn sqlite3_open(filename: *const c_char, pp_db: *mut *mut SqliteDb) -> c_int {
    if !filename.is_null() {
        // SAFETY: 调用方保证 filename 是 NUL 结尾的 UTF-8 字符串。
        if unsafe { CStr::from_ptr(filename) }.to_str().is_err() {
            return SqliteError::ERROR.code();
        }
    }
    if pp_db.is_null() {
        return SqliteError::MISUSE.code();
    }
    let db = SqliteDb::new();
    // SAFETY: pp_db 已校验非 null,写一个有效指针。
    unsafe { *pp_db = Box::into_raw(db) };
    SqliteError::OK.code()
}

/// 关闭数据库,释放 handle。P0 桩。
///
/// C 契约:`int sqlite3_close(sqlite3 *db);`
///
/// # Safety
/// `db` 必须是由 `sqlite3_open` 返回的指针,且不能被 close 两次。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_close(db: *mut SqliteDb) -> c_int {
    if db.is_null() {
        return SqliteError::OK.code();
    }
    // SAFETY: db 由 sqlite3_open 通过 Box::into_raw 产生,这里取回所有权。
    let _ = unsafe { Box::from_raw(db) };
    SqliteError::OK.code()
}

/// 返回最近一次错误的 UTF-8 字符串。P0 桩:返回占位。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_errmsg(db: *mut SqliteDb) -> *const c_char {
    let _ = db;
    ERRSG_NOT_IMPL.as_ptr() as *const c_char
}

/// 返回最近一次错误码。P0 桩:总是返回 OK。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_errcode(db: *mut SqliteDb) -> c_int {
    let _ = db;
    SqliteError::OK.code()
}

/// `sqlite3_open_v2` — 带 flag 的打开。P0 桩。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_open_v2(
    filename: *const c_char,
    pp_db: *mut *mut SqliteDb,
    flags: c_int,
    z_vfs: *const c_char,
) -> c_int {
    let _ = flags;
    let _ = z_vfs;
    // SAFETY: 转发,所有 unsafe 在 sqlite3_open 内部处理。
    unsafe { sqlite3_open(filename, pp_db) }
}

/// `sqlite3_malloc` — 公开 API malloc。
///
/// 严格对齐 C 端 `sqlite-source/src/malloc.c::sqlite3_malloc`:
/// - `n <= 0` → 返回 `NULL`(不再返回"假非 null"指针 — T-0001 临时桩已替换)
/// - `n > 0` → 转发到内部 [`Malloc::malloc64`]
#[no_mangle]
pub unsafe extern "C" fn sqlite3_malloc(n: c_int) -> *mut c_void {
    Malloc::malloc(n, None)
}

/// `sqlite3_malloc64` — 同上但参数是 `sqlite3_uint64`。
///
/// 严格对齐 C 端 `sqlite3_malloc64`(`n == 0 || n > MAX` → NULL)。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_malloc64(n: i64) -> *mut c_void {
    Malloc::malloc64(n as u64, None)
}

/// `sqlite3_free` — 释放。
///
/// 严格对齐 C 端 `sqlite3_free`:`p == NULL` 是 no-op。
#[no_mangle]
pub unsafe extern "C" fn sqlite3_free(p: *mut c_void) {
    Malloc::free(p);
}

// 'static 字符串(嵌入二进制,末尾 \0)
static SQLITE_VERSION_STR: &[u8] = b"3.54.0\0";
static ERRSG_NOT_IMPL: &[u8] = b"not implemented\0";

