//! T-0002 — `sqlite3_malloc` 家族集成测试,严格对齐
//! `sqlite-source/src/malloc.c` 行为。
//!
//! 8 个测试,直接调用内部 API `Malloc` 与公开 FFI `sqlite3_malloc64` /
//! `sqlite3_free`:
//! 1. `malloc(0)` → `NULL`
//! 2. `malloc64(0)` → `NULL`
//! 3. `free(NULL)` → no-op
//! 4. `realloc` 失败时原指针保留(用 `n > MAX` 触发"边界拒绝"路径)
//! 5. 大块 alloc(1 MB)
//! 6. 8 字节对齐
//! 7. OOM 标志读写
//! 8. `realloc(p, 0)` 释放 p 并返回 `NULL`

use libsqlite_rs::{Malloc, SqliteDb, SQLITE_MAX_ALLOCATION_SIZE};
use std::ffi::c_void;
use std::ptr;

/// 1. `malloc(0)` 返回 `NULL` — 对应 C `sqlite3_malloc.c:316-321` 中
/// `n<=0 ? 0 : sqlite3Malloc(n)`。
#[test]
fn malloc_zero_returns_null() {
    // 走 FFI 公开 API(n = c_int = 0)
    let p = unsafe { libsqlite_rs::sqlite3_malloc(0) };
    assert!(p.is_null(), "sqlite3_malloc(0) must return NULL");

    // 走内部 API(u64 path, n=0)
    let p = Malloc::malloc(0u64, None);
    assert!(p.is_null(), "Malloc::malloc(0) must return NULL");
}

/// 2. `malloc64(0)` 返回 `NULL` — 对应 C `sqlite3_malloc64.c:322-327`
/// / `sqlite3Malloc.c:296-309` 中 `n==0` 分支。
#[test]
fn malloc64_zero_returns_null() {
    let p = unsafe { libsqlite_rs::sqlite3_malloc64(0) };
    assert!(p.is_null(), "sqlite3_malloc64(0) must return NULL");

    let p = Malloc::malloc64(0u64, None);
    assert!(p.is_null(), "Malloc::malloc64(0) must return NULL");
}

/// 3. `free(NULL)` 是 no-op — 对应 C `sqlite3_free.c:391-404` 中
/// `if( p==0 ) return;` (IMP: R-49053-54554)。
#[test]
fn free_null_is_noop() {
    unsafe { libsqlite_rs::sqlite3_free(ptr::null_mut()) };
    Malloc::free(ptr::null_mut());
    // 不能 panic,不能污染 size 表
}

/// 4. `realloc` 失败时原指针保留 — 对应 C `sqlite3Realloc.c:511-517`
/// 中 `nBytes>SQLITE_MAX_ALLOCATION_SIZE → return 0`(p 不动)。
///
/// 我们在 realloc 前写入 sentinel,失败后读取,验证原指针仍可用且
/// 内容不变。这是 C 端 `sqlite3DbReallocFinish` 的 `if(!pNew)
/// sqlite3OomFault(db)` 路径的 1:1 行为。
#[test]
fn realloc_failure_preserves_old_pointer() {
    let p = Malloc::malloc64(64, None);
    assert!(!p.is_null());
    // 写入 sentinel
    unsafe { std::ptr::write_bytes(p, 0xABu8, 64) };
    // 触发"边界拒绝"路径:n > MAX → 返回 NULL,但不写 malloc_failed
    let p_new = Malloc::realloc(p, (SQLITE_MAX_ALLOCATION_SIZE + 1) as i64, None);
    assert!(p_new.is_null());
    // 旧指针仍有效,内容未变
    let preserved = unsafe { std::slice::from_raw_parts(p, 64) };
    for &b in preserved {
        assert_eq!(b, 0xAB, "old pointer data must be preserved on realloc failure");
    }
    // 清理
    Malloc::free(p);
}

/// 5. 大块 alloc(1 MB)成功,且能写入/读取。
#[test]
fn large_alloc_succeeds() {
    let n: usize = 1024 * 1024; // 1 MiB
    let p = Malloc::malloc64(n as u64, None);
    assert!(!p.is_null(), "1 MiB alloc must succeed");
    // 写入 + 读回,验证整段可写
    unsafe { std::ptr::write_bytes(p, 0xCDu8, n) };
    let slice = unsafe { std::slice::from_raw_parts(p, n) };
    for &b in slice {
        assert_eq!(b, 0xCD);
    }
    Malloc::free(p);
}

/// 6. 8 字节对齐 — 对应 C 端 `EIGHT_BYTE_ALIGNMENT` 宏断言
/// (`sqlite3Malloc.c:307`)。
#[test]
fn alignment_is_8_bytes() {
    // 不同 size 各试一遍,确认每块都 8 字节对齐
    for size in [1usize, 7, 8, 9, 17, 31, 64, 1024] {
        let p = Malloc::malloc64(size as u64, None);
        assert!(!p.is_null());
        assert_eq!(
            p as usize % 8,
            0,
            "alloc of {size} bytes must be 8-byte aligned (got {p:p})"
        );
        Malloc::free(p);
    }
}

/// 7. OOM 标志读写 — 验证 `SqliteDb::malloc_failed` 的
/// `set_malloc_failed` / `check_malloc_failed` 往返正确(对齐 C
/// `db->mallocFailed`)。
#[test]
fn oom_flag_read_write() {
    let db = SqliteDb::new();
    // 初始为 false
    assert!(!db.check_malloc_failed(), "fresh db must have malloc_failed = false");
    // 写标志
    db.set_malloc_failed();
    // 读回
    assert!(db.check_malloc_failed(), "malloc_failed must reflect set_malloc_failed");
    // 也能通过内部 API 触发:对 db 调 malloc64(big) — 但 big 被 MAX 截住,
    // C 端不写 flag。所以这里只验证 set/check 往返。
}

/// 8. `realloc(p, 0)` 释放 p 并返回 `NULL` — 对应 C
/// `sqlite3Realloc.c:511-514` 中 `nBytes==0 → sqlite3_free(pOld); return 0;`
/// (IMP: R-26507-47431)。
#[test]
fn zero_byte_realloc_frees_and_returns_null() {
    let p = Malloc::malloc64(64, None);
    assert!(!p.is_null());
    // 写入 sentinel 以便验证"释放了"
    unsafe { std::ptr::write_bytes(p, 0xEFu8, 64) };
    let r = Malloc::realloc(p, 0, None);
    assert!(r.is_null(), "realloc(p, 0) must return NULL");
    // p 已被 free,内部 size 表中应已移除(若使用 HashMap 跟踪)
    // 这里不再用 p — 继续 alloc/free 验证后续操作正常
    let q = Malloc::malloc64(32, None);
    assert!(!q.is_null());
    Malloc::free(q);
}

// 静默抑制"c_void 未使用"警告(在某些 feature 组合下)
#[allow(dead_code)]
fn _ensure_c_void_used(_: *mut c_void) {}

